import { expect } from "chai";
import { Address } from "viem";
import { calculateTxHash } from "./eip-712-transaction-hash";

describe("EIP 712 Transaction Hash library", () => {
  it("should correctly calculate a transaction hash", () => {
    const result = calculateTxHash(
      {
        chainId: 1,
        verifyingContract: "0xa62D2a75eb39C12e908e9F6BF50f189641692F2E" as Address,
      },
      {
        to: "0x8D29bE29923b68abfDD21e541b9374737B49cdAD",
        data: "",
        nonce: 0n,
        operation: 1,
        value: 0n,
      },
    );
    expect(result).to.equal("0xf75ab37ff4d43821fc4833a6a3bbe2a042d2f366420240ce3d2460f2c2534f61");
  });
});
